        <div class="rr-card__pair">
          <button class="rr-btn rr-btn--soft" data-action="restart" data-nav>${rb()}<span>Reiniciar fase</span></button>
          <button class="rr-btn rr-btn--soft" data-action="menu" data-nav>${oS()}<span>Menu inicial</span></button>
        </div>
